public final class GifTests {
 static int n;static void ck(boolean value){n++;if(!value)throw new AssertionError("GIF "+n);}static File write(Path dir,byte[] data)throws Exception{Path p=dir.resolve("control.gif");Files.write(p,data);return p.toFile();}static void reject(Path dir,byte[] data)throws Exception{File file=write(dir,data);boolean refused=false;try{GifRaster.read(file);}catch(IOException e){refused=true;}ck(refused);ck(Arrays.equals(data,Files.readAllBytes(file.toPath())));}
 static String hex(byte[] bytes){StringBuilder text=new StringBuilder();for(byte b:bytes)text.append(String.format(Locale.US,"%02x",b&255));return text.toString();}
 public static void main(String[] args)throws Exception{Path dir=Files.createTempDirectory("gif-control-");try{
  for(int size:new int[]{1,2,35})for(boolean local:new boolean[]{false,true})for(boolean interlace:new boolean[]{false,true})for(boolean v89:new boolean[]{false,true}){byte[] bytes=GifFixtures.image(size,size,local,interlace,v89);File file=write(dir,bytes);GifRaster info=GifRaster.read(file);ck(info.width==size&&info.height==size&&info.palette==16);ck(info.interlaced==interlace&&info.transparent==v89&&info.version.equals(v89?"GIF89a":"GIF87a"));ck(Arrays.equals(bytes,Files.readAllBytes(file.toPath())));ck(info.pixel(0,0)==(v89?0:0xff000000));if(size>1)ck(info.pixel(1,1)==0xff463c64);if(size>2)ck(info.pixel(size-1,size-1)==0xffb81464);if(size==35){ck(info.pixel(16,16)==0xff349464);ck(info.pixel(17,17)==0xff66bc64);ck(info.pixel(2,2)==0xff786464);}ck(info.pixel(-1,0)==0&&info.pixel(size,0)==0&&info.pixel(0,-1)==0&&info.pixel(0,size)==0);info.close();info.close();boolean closed=false;try{info.pixel(0,0);}catch(IOException e){closed=true;}ck(closed);}
  byte[] base=GifFixtures.image(35,35,false,false,true);int gce=61,descriptor=69,code=79;ck((base[gce]&255)==0x21&&(base[descriptor]&255)==0x2c&&base[code]==4);for(byte[] bad:new byte[][]{Arrays.copyOf(base,13),Arrays.copyOf(base,base.length-1),Arrays.copyOf(base,base.length+1),GifFixtures.field(base,0,'B'),GifFixtures.field(base,6,0),GifFixtures.field(base,8,0),GifFixtures.field(base,12,1),GifFixtures.field(base,11,16),GifFixtures.field(base,gce+1,0xff),GifFixtures.field(base,gce+1,1),GifFixtures.field(base,gce+2,3),GifFixtures.field(base,gce+3,2),GifFixtures.field(base,gce+3,8),GifFixtures.field(base,gce+3,32),GifFixtures.field(base,gce+4,1),GifFixtures.field(base,gce+6,16),GifFixtures.field(base,gce+7,1),GifFixtures.field(base,descriptor+1,1),GifFixtures.field(base,descriptor+3,1),GifFixtures.field(base,descriptor+5,34),GifFixtures.field(base,descriptor+7,34),GifFixtures.field(base,descriptor+9,8),GifFixtures.field(base,code,1),GifFixtures.field(base,code,9),GifFixtures.field(base,code+1,0)})reject(dir,bad);
  ByteArrayOutputStream repeated=new ByteArrayOutputStream();repeated.write(base,0,base.length-1);repeated.write(base,descriptor,base.length-1-descriptor);repeated.write(0x3b);reject(dir,repeated.toByteArray());byte[] large=base.clone();large[6]=(byte)0x20;large[7]=(byte)0x4e;large[8]=(byte)0x20;large[9]=(byte)0x4e;reject(dir,large);
  ByteArrayOutputStream comments=new ByteArrayOutputStream();comments.write(base,0,gce);for(int i=0;i<1024;i++){comments.write(0x21);comments.write(0xfe);comments.write(0);}comments.write(base,gce,base.length-gce);reject(dir,comments.toByteArray());ByteArrayOutputStream manyBlocks=new ByteArrayOutputStream();manyBlocks.write(base,0,gce);manyBlocks.write(0x21);manyBlocks.write(0xfe);for(int i=0;i<65537;i++){manyBlocks.write(1);manyBlocks.write(0);}manyBlocks.write(0);manyBlocks.write(base,gce,base.length-gce);reject(dir,manyBlocks.toByteArray());reject(dir,GifFixtures.field(base,4,'7'));ck(GifRaster.read(write(dir,GifFixtures.field(base,gce+3,5))).transparent);
  for(byte[] bad:new byte[][]{GifFixtures.fixedCodes(1,1,4,0,17),GifFixtures.fixedCodes(1,1,4,16,0),GifFixtures.fixedCodes(1,1,4,16,31,17),GifFixtures.fixedCodes(1,1,4,16,18,17),GifFixtures.fixedCodes(2,1,4,16,1,17),GifFixtures.fixedCodes(1,1,4,16,1,1,17),GifFixtures.fixedCodes(1,1,8,256,16,257)})reject(dir,bad);
  try(GifRaster info=GifRaster.read(write(dir,GifFixtures.fixedCodes(21,1,4,16,1,18,19,20,21,22,17)))){for(int x=0;x<21;x++)ck(info.pixel(x,0)==0xff5080b0);}try(GifRaster info=GifRaster.read(write(dir,GifFixtures.fixedCodes(1,1,8,256,1,257)))){ck(info.pixel(0,0)==0xff5080b0);}
  for(boolean clear:new boolean[]{false,true}){try(GifRaster info=GifRaster.read(write(dir,GifFixtures.literalStream(257,17,clear)))){ck(info.width==257&&info.height==17);for(int[] point:new int[][]{{0,0,0},{1,1,0xff66bc64},{128,8,0xff00ff00},{256,16,0}})ck(info.pixel(point[0],point[1])==point[2]);}}
  int[] storm=new int[1100];Arrays.fill(storm,16);storm[1098]=1;storm[1099]=17;reject(dir,GifFixtures.fixedCodes(1,1,4,storm));File timed=write(dir,base);Method read=GifRaster.class.getDeclaredMethod("read",File.class,long.class);read.setAccessible(true);boolean expired=false;try{read.invoke(null,timed,0L);}catch(InvocationTargetException e){expired=e.getCause() instanceof IOException&&e.getCause().getMessage().contains("времени");}ck(expired&&Arrays.equals(base,Files.readAllBytes(timed.toPath())));boolean interrupted=false;Thread.currentThread().interrupt();try{GifRaster.read(timed);}catch(IOException e){interrupted=e.getMessage().contains("прервано");}finally{Thread.interrupted();}ck(interrupted);
  Path fixtures=args.length>0?Paths.get(args[0]):Paths.get("owned-projects/tests/fixtures/gif");for(String line:Files.readAllLines(fixtures.resolve("manifest.tsv"))){String[] fields=line.split("\t");File file=fixtures.resolve(fields[0]).toFile();ck(hex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file.toPath()))).equals(fields[1]));try(GifRaster info=GifRaster.read(file)){ck(info.width==Integer.parseInt(fields[3])&&info.height==Integer.parseInt(fields[4]));MessageDigest digest=MessageDigest.getInstance("SHA-256");for(int y=0;y<info.height;y++)for(int x=0;x<info.width;x++){int pixel=info.pixel(x,y);digest.update((byte)(pixel>>>16));digest.update((byte)(pixel>>>8));digest.update((byte)pixel);digest.update((byte)(pixel>>>24));}ck(hex(digest.digest()).equals(fields[2]));}}
  File oversized=dir.resolve("oversized.gif").toFile();try(RandomAccessFile file=new RandomAccessFile(oversized,"rw")){file.setLength(GifRaster.MAX_FILE+1);}boolean refused=false;try{GifRaster.read(oversized);}catch(IOException e){refused=true;}ck(refused&&oversized.length()==GifRaster.MAX_FILE+1);System.out.println("GIF indexed/LZW: "+n+" assertions passed");
 }finally{try(java.util.stream.Stream<Path> files=Files.walk(dir)){files.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new UncheckedIOException(e);}});}}}
}
